for(uint256 i = 0; i < addres.length; i++) {
if(_isExcludedFromFee[addres[i]] != enable) {
_isExcludedFromFee[addres[i]] = enable;
}
}
}

function isFeeWhiteList(address addr) public view returns(bool) {
