if (0 == startTradeBlock) {
require(0 < startAddLPBlock && _swapPairList[recipient], "ERC20:operater action is not AddLiquidity");
}
if (block.number < startTradeBlock.add(killBlockNumber)) {
_funTransfer(sender, recipient, amount);
return;
