require(0 == startAddLPBlock, "ERC20: startAddLP has been set");
startAddLPBlock = block.number;
}

function closeAddLP() external onlyOwner {
require(startAddLPBlock > 0, "ERC20: startAddLP has not been set");
startAddLPBlock = 0;
}

